 resize(){const w=this.host.clientWidth,h=this.host.clientHeight;if(!w||!h)return;this.canvas.width=Math.min(720,Math.round(w));this.canvas.height=Math.round(this.canvas.width*h/w);this.rays=null;this.dirty=true;}
 async load(mode){const id=++this.loadId;this.mode=mode;this.stop();this.reset();if(mode==='flight')this.makeTerrain();else{const path=mode==='temple'?'assets/immersive/ram-mandir-360.jpg':'assets/immersive/gosaikunda-360.jpg';let pixels=this.cache.get(path);if(!pixels){const img=new Image();img.src=path;await img.decode();const c=document.createElement('canvas');c.width=2048;c.height=1024;const cx=c.getContext('2d',{willReadFrequently:true});cx.drawImage(img,0,0,c.width,c.height);pixels=cx.getImageData(0,0,c.width,c.height);this.cache.set(path,pixels);}if(id!==this.loadId)return;this.pixels=pixels;}if(id!==this.loadId)return;this.resize();this.draw(0);this.start();}
 makeTerrain(){const n=76,step=320/n;this.vertices=[];this.triangles=[];const height=(x,z)=>{const peaks=[[-66,-55,60,32],[3,-85,88,33],[73,-66,74,31],[-100,25,46,29],[98,13,55,35],[10,66,27,50]];let h=4;for(const [px,pz,amp,s]of peaks)h+=amp*Math.exp(-((x-px)**2+(z-pz)**2)/(s*s));h+=(Math.sin(x*.11+Math.sin(z*.07)*2)*Math.cos(z*.09)+Math.sin(x*.31+z*.25)*.25)*(3+h*.09);return Math.max(.3,h*(1-Math.exp(-Math.pow((x-12*Math.sin(z*.035))/12,2))*.72));};for(let j=0;j<=n;j++)for(let i=0;i<=n;i++){const x=i*step-160,z=j*step-160;this.vertices.push([x,height(x,z),z]);}for(let j=0;j<n;j++)for(let i=0;i<n;i++){const a=j*(n+1)+i,b=a+1,c=a+n+1,d=c+1;this.triangles.push([a,c,b],[b,c,d]);}for(const t of this.triangles){const a=this.vertices[t[0]],b=this.vertices[t[1]],c=this.vertices[t[2]],h=(a[1]+b[1]+c[1])/3;const ab=b.map((v,i)=>v-a[i]),ac=c.map((v,i)=>v-a[i]),normal=[ab[1]*ac[2]-ab[2]*ac[1],ab[2]*ac[0]-ab[0]*ac[2],ab[0]*ac[1]-ab[1]*ac[0]];const len=Math.hypot(...normal);const shade=.72+.3*Math.max(0,(-normal[0]*.5+normal[1]*.8-normal[2]*.3)/len);let col=h>49?[222,230,225]:h>28?[112,128,120]:[49,88,69];t.color=col.map(v=>v*shade);}}
 drawPanorama(){const {width:w,height:h}=this.canvas;if(!this.rays){this.rays=new Float32Array(w*h*3);const tan=Math.tan(this.fov*Math.PI/360),aspect=w/h;for(let y=0;y<h;y++)for(let x=0;x<w;x++){const k=(y*w+x)*3,rx=(2*(x+.5)/w-1)*tan*aspect,ry=(1-2*(y+.5)/h)*tan,len=Math.hypot(rx,ry,1);this.rays[k]=rx/len;this.rays[k+1]=ry/len;this.rays[k+2]=-1/len;}this.frame=this.ctx.createImageData(w,h);}const yaw=this.yaw*Math.PI/180,pitch=this.pitch*Math.PI/180,cy=Math.cos(yaw),sy=Math.sin(yaw),cp=Math.cos(pitch),sp=Math.sin(pitch),src=this.pixels.data,tw=this.pixels.width,th=this.pixels.height,out=this.frame.data;for(let k=0,o=0;k<this.rays.length;k+=3,o+=4){const rx=this.rays[k],ry=this.rays[k+1]*cp-this.rays[k+2]*sp,rz=this.rays[k+1]*sp+this.rays[k+2]*cp,x=rx*cy+rz*sy,z=-rx*sy+rz*cy;let u=(.5+Math.atan2(z,x)/(2*Math.PI))*tw;const v=clamp(Math.floor((.5-Math.asin(clamp(ry,-1,1))/Math.PI)*th),0,th-1);const s=(v*tw+(Math.floor(u)%tw+tw)%tw)*4;out[o]=src[s];out[o+1]=src[s+1];out[o+2]=src[s+2];out[o+3]=255;}this.ctx.putImageData(this.frame,0,0);}
 drawFlight(){const cx=this.ctx,w=this.canvas.width,h=this.canvas.height;const sky=cx.createLinearGradient(0,0,0,h);sky.addColorStop(0,'#6a929e');sky.addColorStop(.65,'#c5c7b5');sky.addColorStop(1,'#9eaf9c');cx.fillStyle=sky;cx.fillRect(0,0,w,h);const camera=[Math.sin(this.angle)*this.distance,this.elevation,Math.cos(this.angle)*this.distance],normalize=v=>{const l=Math.hypot(...v);return v.map(n=>n/l)},forward=normalize([-camera[0],25-camera[1],-25-camera[2]]),right=normalize([-forward[2],0,forward[0]]),up=[right[1]*forward[2]-right[2]*forward[1],right[2]*forward[0]-right[0]*forward[2],right[0]*forward[1]-right[1]*forward[0]],dot=(a,b)=>a[0]*b[0]+a[1]*b[1]+a[2]*b[2],scale=h/(2*Math.tan(72*Math.PI/360));const projected=this.vertices.map(v=>{const d=v.map((x,i)=>x-camera[i]),z=dot(d,forward);return[w/2+dot(d,right)*scale/z,h/2-dot(d,up)*scale/z,z];});const faces=[];for(const t of this.triangles){const a=projected[t[0]],b=projected[t[1]],c=projected[t[2]];if(a[2]<2||b[2]<2||c[2]<2)continue;if(Math.max(a[0],b[0],c[0])<0||Math.min(a[0],b[0],c[0])>w||Math.max(a[1],b[1],c[1])<0||Math.min(a[1],b[1],c[1])>h)continue;faces.push({a,b,c,color:t.color,z:(a[2]+b[2]+c[2])/3});}faces.sort((a,b)=>b.z-a.z);for(const f of faces){const fog=clamp((f.z-45)/340,0,.75),col=f.color.map((n,i)=>Math.round(n*(1-fog)+[177,193,184][i]*fog));cx.fillStyle=`rgb(${col.join(',')})`;cx.strokeStyle=cx.fillStyle;cx.lineWidth=.65;cx.beginPath();cx.moveTo(f.a[0],f.a[1]);cx.lineTo(f.b[0],f.b[1]);cx.lineTo(f.c[0],f.c[1]);cx.closePath();cx.fill();cx.stroke();}}
 draw(delta){if(this.auto){if(this.mode==='flight')this.angle+=delta*.045;else this.yaw+=delta*2.2;this.dirty=true;}if(!this.dirty)return;if(this.mode==='flight')this.drawFlight();else if(this.pixels)this.drawPanorama();this.onFrame?.(this.mode==='flight'?this.angle*180/Math.PI:this.yaw);this.dirty=false;}
